public boolean isNumber(String s) {
    if (s == null || s.isBlank()) {
        return false;
    }

    s = s.trim();

    boolean hasDot = false;
    boolean hasDigit = false;
    boolean hasE = false;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);

        if (Character.isDigit(c)) {
            hasDigit = true;
        } else if (c == '.') {
            if (hasDot || hasE) {
                return false;
            }
            hasDot = true;
        } else if (c == 'e' || c == 'E') {
            if (hasE || !hasDigit) {
                return false;
            }
            hasE = true;
            hasDigit = false; // Reset digit flag for the exponent
        } else if (c == '-' || c == '+') {
            if (i != 0 && s.charAt(i - 1) != 'e' && s.charAt(i - 1) != 'E') {
                return false;
            }
        } else {
            return false;
        }
    }

    return hasDigit;
}

